{"task": "Find log lines whose message contains a MAC address formed from six colon-separated two-character hex blocks", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}')"}
{"task": "List event paths that embed a standard UUID made of five hyphen-separated hex groups", "sql": "SELECT id, user_id, path FROM events WHERE regexp_like(path, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'i')"}
{"task": "Count per-service log lines that contain an IPv4 address built from three repeated dotted octet groups plus a final octet", "sql": "SELECT service, COUNT(*) AS ip_mentions FROM logs WHERE regexp_like(message, '(\\d{1,3}\\.){3}\\d{1,3}') GROUP BY service ORDER BY ip_mentions DESC"}
{"task": "Tag each log message as containing a serial-number identifier made of three repeated four-character alphanumeric blocks plus a final block", "sql": "SELECT ts, message, CASE WHEN regexp_like(message, '([A-Z0-9]{4}-){3}[A-Z0-9]{4}') THEN 'serial_id' ELSE 'no_serial' END AS id_type FROM logs"}
{"task": "Find event paths whose first segments are three repeated two-letter country-code blocks", "sql": "SELECT id, path FROM events WHERE regexp_like(path, '^(/[A-Z]{2}){3}/')"}
{"task": "Detect log messages leaking a credit-card-like number built from three repeated four-digit groups plus a final group", "sql": "SELECT ts, service, message FROM logs WHERE level IN ('ERROR','WARN') AND regexp_like(message, '(\\d{4}[- ]){3}\\d{4}')"}
{"task": "List distinct event paths containing a tracking code formed from a prefix followed by two repeated three-digit groups and a final group", "sql": "SELECT DISTINCT path FROM events WHERE regexp_like(path, 'TRK-(\\d{3}-){2}\\d{3}')"}
{"task": "Find error-level logs whose message contains a 16-character hex token composed of two repeated eight-character hex blocks", "sql": "SELECT ts, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '([0-9a-f]{8}){2}', 'i')"}
{"task": "Find events whose path contains an order id formed from a letter prefix and three repeated two-digit groups", "sql": "SELECT id, user_id, path, status FROM events WHERE regexp_like(path, 'ORD-([0-9]{2}){3}')"}
{"task": "List distinct services whose logs mention a dotted build/version id made of two repeated two-character alphanumeric groups plus a final group", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '([A-Za-z0-9]{2}\\.){2}[A-Za-z0-9]{2}', 'i')"}

